"""Prepare the authorized post-publication docs and compact validation evidence."""
import copy,gzip,hashlib,json,re,shutil,sys
from pathlib import Path
cfg=json.loads(Path(sys.argv[1]).read_text());root=Path(cfg['sourceRoot']);read=lambda p:json.loads(Path(p).read_text())
record=read(cfg['recordingVerification']);main=read(cfg['mainGate']);harness=read(cfg['harnessGate']);beta=read(cfg['betaVerification']);release=record['publishedRelease']
assert record['status']=='passed' and record['fourIndependentSerializedCapturesExactlyEqual'] and record['approvedVersionLeaves']==204
assert main['candidateConjunctionVerified'] and harness['candidateConjunctionVerified'] and beta['status']=='passed'
assert record['commit']==main['head']==beta['commit'] and record['tree']==main['tree']==beta['tree']
assert release['tagName']=='v0.10.0' and release['publishedAt'] and not release['isDraft'] and not release['isPrerelease']
assert not any((root/p).exists() for p in ['tests/baselines/release-version-mapping.json','tests/baselines/release-accessibility-scope.json','tests/e2e/release_version_mapping.py','tests/unit/test_release_version_mapping.py'])
new_golden=hashlib.sha256((root/'tests/baselines/characterize.json.gz').read_bytes()).hexdigest();assert new_golden==record['newGoldenCompressedSha256']
evidence=root/'tests/baselines/evidence/release-0.10.0/completion';evidence.mkdir(parents=True,exist_ok=False)
for label,path in [('published-tag-recording',cfg['recordingVerification']),('main-with-settled-harness',cfg['mainGate']),('harness-pr32',cfg['harnessGate']),('beta-deployment',cfg['betaVerification'])]:
 value=Path(path).read_bytes();(evidence/(label+'.json.gz')).write_bytes(gzip.compress(value,mtime=0))
(evidence/'published-release.json').write_text(json.dumps(release,indent=2)+'\n')
source_out=Path(cfg['mainGate']).parents[2]
for name,source in [('publication-beta-evidence.sha256.json',source_out/'publication-beta-evidence.sha256.json'),('harness-pr32-archive.sha256.json',Path(cfg['harnessGate']).parent/'immutable-evidence.sha256.json'),('main-harness-archive.sha256.json',Path(cfg['mainGate']).parent/'immutable-evidence.sha256.json'),('published-recording-archive.sha256.json',Path(cfg['recordingVerification']).parent/'immutable-evidence.sha256.json')]:
    assert source.is_file(),source
    shutil.copyfile(source,evidence/name)

summary=dict(status='published 0.10.0; explicit baseline promotion and mapping expiry prepared for own gate',tag=record['tag'],commit=record['commit'],tree=record['tree'],publishedRelease=release['url'],publishedTagRecordingRun=record['runId'],capturesPerRun=102,independentCiJobs=2,runsPerJob=2,fourSerializedRepeatsExactlyEqual=True,approvedVersionLeaves=204,residualDifference=None,oldGoldenSha256='98c26a9db67b9e73a70b53628fb7b12763d41e91a303f9e3fa12f68af650be50',newGoldenSha256=new_golden,sixNamespacesAbsorbed=True,apiAdditionsRemaining=0,mappingHelperAndBothScopesRemoved=True,trackedLet=249,dependencyCounts=dict(trajectory=8,vibration=13,symmetry=11,periodic=11,pubchem=13),mainOrdinaryGateRun=main['runId'],harnessOrdinaryGateRun=harness['runId'],mainCounts={k:main['browser'][k] for k in ['passed','failed','total']},mainLooks=main['appearanceMaterialPresetIntermittent'],mainTiming=main['timing'],mainConstruction=main['constructionOrder'],carriedProductPriority=[25,17],otherCarried=[3,4,11],maintenance=[5,14,15],closedTestSynchronizationIssue=21,expectedJsTests=433,expectedPythonTests=60,noProductionChanges=True)
(evidence/'summary.json').write_text(json.dumps(summary,indent=2)+'\n')
# Current instructions supersede historical freeze checkpoints without erasing them.
p=root/'AGENTS.md';s=p.read_text();before=s[:s.index('## Purpose')];(evidence/'agents-before-finalization.txt.gz').write_bytes(gzip.compress(before.encode(),mtime=0))
intro=f'''# AGENTS.md

## Refactor and 0.10.0 release status

Stage 5 is complete and 0.10.0 is published at `{record['commit']}`. No user-facing changes or production defect fixes were included. The three groups were: 5a PR #26 trajectory shadows 262 → 260 lets, 8 used dependencies, construction 29 app / 129 module bindings; 5b #27 vibration 260 → 256, 13 dependencies, 16/161; 5c #28 symmetry 256 → 249, 11 dependencies, 27/125. Final app count is 249 (16 below Stage 3's accepted 265). Periodic-table has 11 used inputs; PubChem 13. Continuous vibration phase advancement and its 0.2s cap remain unchanged. The duplicated-clock hypothesis for #11 is refuted.

The ordinary gate remains **34 passing / 3 failing / 37**, exactly axis Escape/canvas focus, Coordinates Delete/selection-card interception and Smoke #11 at trajectory OR vibration idle wait after the second download. Match `(suite, workflow)`, never line number. Missing, additional or changed workflows, including 35/2, stop. Require 102 exact goldens twice, the fixed 52-slot composition across eight contexts/all minima, checks/units/WebKit and the inverse construction-order audit. Workbench is 47 live + 5 known-absent; legacy 48 + 4. The latest pre-publication main conjunction is [run {main['runId']}]({main['runUrl']}); the baseline promotion still receives its own first ordinary gate.

[Diagnostic 39154813750](https://github.com/evangelistalab/vibemol/actions/runs/39154813750) observed the hint auto-hide fade: tagged 3/3 original-suite passes, accepted PR tree 2/3, main 1/3. Actual compositor frames refuted a pre-canvas-paint cause in the failures; the hint theme-background transition had finished. Separate harness PR #32 waits for `document.fonts.ready`, completed CSS transitions and two frames before every axe scan. Preserve the original incomplete baseline. The named set in `accessibility_contract.py` covers only light/dark Calculations `#hint` with exact `color-contrast`/`imgNode` and related `#canvas`; incomplete remains incomplete. New unresolved targets, changed reasons/canvases and violations still fail. Assertions log comparands on both outcomes. Diagnostics never supply acceptance; the retrospective records why case classification deferred the specified class fix twice.

The temporary 0.9.5 → 0.10.0 projection is **expired and removed**, including both immutable tree scopes, helper/call and 19 temporary tests. Published-tag CI [run {record['runId']}]({record['runUrl']}) recorded 102 captures twice on each of two independent workers; all four serializations match exactly. Exactly 204 approved full-path version leaves and zero residual difference were verified. The new 0.10.0 goldens include all six extracted namespaces, so the additive API list is empty. Future version values compare exactly; no version tolerance remains. Permanent negative controls cover both `session.appVersion` and `session.preset.appVersion`.

The native release matrix completed all four modes, both themes and 1512/1280/1024 with 204 session Save/Open pairs and 816 mode observations. The deployed beta also resolves all six namespaces and its runtime source hashes. No standalone HTML exporter exists; it remains an unbuilt 0.11+ candidate and was not a release gate. Product priority is **#25 → #17**; #3/#4/#11 and maintenance #5/#14/#15 remain carried. #21 is closed as test synchronization. The material-preset intermittent remains open; every ordinary run reports Looks duration and both material-family paths, while diagnostics/recordings state when coverage was not exercised.

'''
s=intro+s[s.index('## Purpose'):]
needle='- **Release ordering, corrected by the human:**'
lines=s.splitlines();lines=[line+' **Completed:** 0.10.0 is published; the explicit four-repeat tag recording was promoted and both temporary mapping scopes/helper/tests are removed.' if line.startswith(needle) else line for line in lines];p.write_text('\n'.join(lines)+'\n')
p=root/'README.md';s=p.read_text();s,n=re.subn(r'^- Current release:.*$', '- Current release: **v0.10.0** — [release notes](docs/releases/v0.10.0.md). This release contains no user-facing changes. [VibeMol](https://vibemol.org/) opens the Workbench interface by default.',s,count=1,flags=re.M);assert n==1;p.write_text(s)
p=root/'docs/releases/v0.10.0.md';assert not p.exists();p.write_text(Path(cfg['releaseNotes']).read_text()+f'\nPublished tag: `{record["commit"]}`. Accepted main CI: [run {main["runId"]}]({main["runUrl"]}). Published baseline: [run {record["runId"]}]({record["runUrl"]}), four exact 102-capture repetitions; the temporary 204-leaf mapping is removed.\n')
p=root/'docs/refactor-release-retrospective.md';s=p.read_text();s+=f'\nThe separate harness PR and unchanged-production main run {main["runId"]} passed their full first conjunctions. Looks took {main["appearanceMaterialPresetIntermittent"]["looksSeconds"]}s and completed both material-family paths; its intermittent remains open. The release was published and the subsequent four-repeat tag recording promoted, with both temporary scopes removed. Class-repair completion is supported by its negative controls and ordinary gates, not by selecting passing diagnostic attempts.\n';p.write_text(s)
p=root/'tests/baselines/browser-suite.json';d=read(p);assert d['expected']==dict(passed=34,failed=3,total=37);d['accessibilitySynchronizationCorrection']=dict(diagnostic='https://github.com/evangelistalab/vibemol/actions/runs/39154813750',harnessPr=32,mechanism='hint auto-hide fade, not a pre-canvas-paint scan in the measured failures',readiness='fonts ready, CSS transitions completed, two frames',namedIncompleteContract='tests/e2e/accessibility_contract.py',baselineIncompletePreserved=True,newUnresolvedOutsideNamedSetFails=True,ordinaryGateUnchanged=True,evidence='tests/baselines/evidence/release-0.10.0/accessibility-hint-timing');p.write_text(json.dumps(d,indent=2)+'\n')
p=root/'tests/baselines/refactor-stage-risk.json';d=read(p);d['historicalReleaseCandidatePlanning']=d['releaseCandidate'];d.setdefault('historicalLatestGateBeforeRelease',copy.deepcopy(d['latestCiGateAttempt']));d['latestCiGateAttempt']=dict(pr=main['pr'],head=main['head'],run=main['runUrl'],attempt=1,status='first complete main conjunction after separate accessibility harness fix; no production delta',counts=summary['mainCounts'],issue11Workflow=main['browser']['issue11Workflow'],vibrationReached=main['browser']['vibrationReachedThisRun'],wallTimeVs13293=main['timing'],appearanceMaterialPresetIntermittent=main['appearanceMaterialPresetIntermittent'],evidence='tests/baselines/evidence/release-0.10.0/completion/main-with-settled-harness.json.gz')
d['currentBrowserBaseline'].update(evidence=d['latestCiGateAttempt']['evidence'],provenance='Same production tree after the separately authorized accessibility class fix; own first complete main gate',comparison='Current 34/3/37 exact three-workflow gate; 35/2 remains a stop');d['currentBrowserBaseline']['gate'].update(passed=34,failed=3,total=37,satisfied=True,status='accepted first complete main gate'+str(main['runId']));d['releaseCandidate']=summary;d['releaseVersionMappingAuthority'].update(status='expired and removed after explicit published-tag baseline recording',recordingRun=record['runId'],newGoldenSha256=new_golden,temporaryHelperScopesTestsRemoved=True,futureVersionValuesMustMatchExactly=True);d['scope']='Completed structural 0.10.0 refactor preserving runtime APIs, behavior, visuals and session format. All six extracted namespaces are in the published golden; no additive or version-mapping exception remains. 0.9.x product defects ship separately.';p.write_text(json.dumps(d,indent=2)+'\n')
# The deployment reset proved that removing CNAME also removes beta's hostname.
# Correct the publishing workflow, while the primary CNAME remains unchanged.
p=root/'.github/workflows/deploy-beta.yml';text=p.read_text()
before="          # The production domain belongs to main, not the beta mirror.\n          rm -f CNAME"
after="          # Publish the mirror with its existing beta hostname.\n          printf '%s' beta.vibemol.org > CNAME"
assert text.count(before)==1
p.write_text(text.replace(before,after))
(evidence/'beta-hostname-correction.json').write_text(json.dumps(dict(observed='The old workflow removed the existing beta CNAME and Pages reset to the organization URL.',restoration='Exact prior beta.vibemol.org CNAME bytes restored in mirror 57f072dbfb032614354b0bf36bc86189bcc78fc0',sourceDeploymentRun=39161260923,fix='Publishing workflow writes beta.vibemol.org instead of deleting CNAME',primaryProductionCnameUnchanged='vibemol.org',appRuntimeUnchanged=True,correctedWorkflowMustBeDeployedAfterMerge=True),indent=2)+'\n')
print(json.dumps(dict(status='post-publication docs prepared for own first CI',version='0.10.0',lets=249,pythonTests=60,newGoldenSha256=new_golden),indent=2))
